package com.gerenciadorrural.modules.herd.api;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties; import com.fasterxml.jackson.databind.annotation.JsonDeserialize; import com.gerenciadorrural.modules.herd.application.*; import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.modules.organizations.api.ResolvedTenantContext; import com.gerenciadorrural.shared.tenancy.TenantContext; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/herd/paddocks") public class PaddockController {private final PaddockCurrentFarm paddocks;public PaddockController(PaddockCurrentFarm paddocks){this.paddocks=paddocks;}@PostMapping public ResponseEntity<PaddockItem> create(@ResolvedTenantContext TenantContext c,@RequestBody CreateRequest r){var x=paddocks.create(c,r.id(),r.name(),r.code());return ResponseEntity.status(x.created()?HttpStatus.CREATED:HttpStatus.OK).cacheControl(CacheControl.noStore()).body(PaddockItem.from(x.paddock()));}@GetMapping public ResponseEntity<Page> list(@ResolvedTenantContext TenantContext c,@RequestParam(required=false) String status,@RequestParam(required=false) String search,@RequestParam(required=false) Integer page,@RequestParam(required=false) Integer size,HttpServletRequest r){allowed(r,"status","search","page","size");try{var x=paddocks.list(c,status==null?null:PaddockStatus.valueOf(status),search,page==null?0:page,size==null?50:size);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Page.from(x));}catch(IllegalArgumentException e){throw new HerdAnimalQueryException();}}@GetMapping("/{id}") public ResponseEntity<PaddockItem> get(@ResolvedTenantContext TenantContext c,@PathVariable UUID id){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(PaddockItem.from(paddocks.get(c,id)));}@PatchMapping("/{id}") public ResponseEntity<PaddockItem> patch(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody PatchRequest r){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(PaddockItem.from(paddocks.patch(c,id,r.expectedVersion(),r.name(),r.code(),r.status())));}@GetMapping("/{id}/occupancy") public ResponseEntity<Occupancy> occupancy(@ResolvedTenantContext TenantContext c,@PathVariable UUID id){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Occupancy.from(paddocks.occupancy(c,id)));}@GetMapping("/{id}/animals") public ResponseEntity<Animals> animals(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestParam(required=false) Integer page,@RequestParam(required=false) Integer size,HttpServletRequest r){allowed(r,"page","size");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Animals.from(paddocks.animals(c,id,page==null?0:page,size==null?50:size)));}private static void allowed(HttpServletRequest r,String... a){if(!Set.of(a).containsAll(r.getParameterMap().keySet())||r.getParameterMap().values().stream().anyMatch(v->v.length!=1))throw new HerdAnimalQueryException();}@JsonIgnoreProperties(ignoreUnknown=false) @JsonDeserialize(using=PaddockCreateRequestDeserializer.class) public record CreateRequest(UUID id,String name,String code){}@JsonIgnoreProperties(ignoreUnknown=false) @JsonDeserialize(using=PaddockPatchRequestDeserializer.class) public record PatchRequest(Long expectedVersion,HerdAnimalPatch<String> name,HerdAnimalPatch<String> code,HerdAnimalPatch<PaddockStatus> status){}public record Page(List<PaddockWithOccupancy> items,int page,int size,long totalElements,int totalPages){static Page from(PaddockPage x){return new Page(x.items().stream().map(p->new PaddockWithOccupancy(PaddockItem.from(p),p.occupancy())).toList(),x.page(),x.size(),x.totalElements(),x.totalPages());}}public record PaddockWithOccupancy(String id,String name,String code,String status,long version,long occupancy){PaddockWithOccupancy(PaddockItem p,long n){this(p.id(),p.name(),p.code(),p.status(),p.version(),n);}}public record Occupancy(PaddockItem paddock,long totalAnimals,Map<String,Long> countsByStatus){static Occupancy from(PaddockCurrentFarm.Occupancy x){Map<String,Long> m=new TreeMap<>();x.countsByStatus().forEach((k,v)->m.put(k.name(),v));return new Occupancy(PaddockItem.from(x.paddock()),x.totalAnimals(),m);}}public record Animals(List<HerdAnimalController.Item> items,int page,int size,long totalElements,int totalPages){static Animals from(HerdAnimalPage p){return new Animals(p.items().stream().map(HerdAnimalController.Item::from).toList(),p.page(),p.size(),p.totalElements(),p.totalPages());}}}
